using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

namespace RhythmSlashRunner.Presentation
{
    /// <summary>
    /// Round 34: English. The game is written in Japanese; every Text built through <see cref="UiKit.Label"/> carries an
    /// <see cref="L10nText"/> that swaps what is shown at display time: a whole-string match first, else every known
    /// Japanese fragment (longest first) — concatenated lines are made of those fragments and numbers. The table is
    /// Resources/l10n_en.json, generated by tools/l10n/en.py.
    /// </summary>
    public static class L10n
    {
        [Serializable] sealed class Entry { public string ja; public string en; }
        [Serializable] sealed class Table { public Entry[] entries; }

        static Dictionary<string, string> exact;
        static List<KeyValuePair<string, string>> fragments;
        static readonly Dictionary<string, string> memo = new Dictionary<string, string>();

        /// <summary>"ja" or "en". Set from the profile (empty there = the device language).</summary>
        public static string Language = "ja";
        public static bool English { get { return Language == "en"; } }

        public static string Auto() { return Application.systemLanguage == SystemLanguage.Japanese ? "ja" : "en"; }

        static void Load()
        {
            if (exact != null) return;
            exact = new Dictionary<string, string>();
            fragments = new List<KeyValuePair<string, string>>();
            TextAsset asset = Resources.Load<TextAsset>("l10n_en");
            if (asset == null) return;
            Table t = JsonUtility.FromJson<Table>(asset.text);
            if (t == null || t.entries == null) return;
            foreach (Entry e in t.entries)
            {
                if (string.IsNullOrEmpty(e.ja)) continue;
                exact[e.ja] = e.en ?? "";
                fragments.Add(new KeyValuePair<string, string>(e.ja, e.en ?? ""));
            }
            fragments.Sort((a, b) => b.Key.Length.CompareTo(a.Key.Length));
        }

        public static bool HasJapanese(string s)
        {
            if (string.IsNullOrEmpty(s)) return false;
            foreach (char c in s) if ((c >= '぀' && c <= 'ヿ') || (c >= '一' && c <= '鿿') || (c >= '！' && c <= '｠')) return true;
            return false;
        }

        public static string T(string s)
        {
            if (!English || !HasJapanese(s)) return s;
            string done;
            if (memo.TryGetValue(s, out done)) return done;
            Load();
            string r;
            if (!exact.TryGetValue(s, out r))
            {
                r = s;
                foreach (KeyValuePair<string, string> f in fragments)
                {
                    if (!HasJapanese(r)) break;
                    if (r.IndexOf(f.Key, StringComparison.Ordinal) >= 0) r = r.Replace(f.Key, f.Value);
                }
            }
            if (memo.Count > 2000) memo.Clear();
            memo[s] = r;
            return r;
        }

        /// <summary>Forget cached lines (after switching language).</summary>
        public static void Reset() { memo.Clear(); }
    }

    /// <summary>Keeps one Text in the current language (checks when its text changes).</summary>
    [DisallowMultipleComponent]
    public sealed class L10nText : MonoBehaviour
    {
        Text text;
        string shown;

        void Awake() { text = GetComponent<Text>(); }

        void LateUpdate()
        {
            if (text == null || !L10n.English) return;
            string now = text.text;
            if (ReferenceEquals(now, shown) || now == shown) return;
            string t = L10n.T(now);
            if (!ReferenceEquals(t, now)) text.text = t;
            shown = text.text;
        }
    }
}
